    public StyleBoxFlat box(Color fill,Color border,int radius,int padding){var style=new StyleBoxFlat{BgColor=fill,BorderColor=border,ContentMarginLeft=padding,ContentMarginRight=padding,ContentMarginTop=padding,ContentMarginBottom=padding};style.SetBorderWidthAll(1);style.SetCornerRadiusAll(radius);return style;}
    public Texture2D icon(Control owner,string name){var icons=owner.Get("_icons").AsGodotDictionary();if(icons.ContainsKey(name))return icons[name].As<Texture2D>();string svg="<svg xmlns='http://www.w3.org/2000/svg' width='24' height='24' viewBox='0 0 24 24'><g fill='none' stroke='#c5dfdf' stroke-width='1.6' stroke-linecap='round' stroke-linejoin='round'>"+Get(Glyphs,name,Glyphs["image"]).AsString()+"</g></svg>";using var bitmap=new Image();bitmap.LoadSvgFromString(svg);var texture=ImageTexture.CreateFromImage(bitmap);icons[name]=texture;return texture;}
    public void build_theme(Control owner)
    {
        var skin=new Theme{DefaultFontSize=13};foreach(string kind in new[]{"Button","MenuButton","OptionButton"}){skin.SetStylebox("normal",kind,box(new Color("202c3a"),new Color("344356"),6,8));skin.SetStylebox("hover",kind,box(new Color("2d4153"),new Color("5c7b91"),6,8));skin.SetStylebox("pressed",kind,box(new Color("21584f"),new Color("6ae2c3"),6,8));skin.SetStylebox("focus",kind,box(Colors.Transparent,new Color("74ddca"),6,1));skin.SetColor("font_color",kind,new Color("d6e4f0"));skin.SetColor("font_hover_color",kind,Colors.White);skin.SetFontSize("font_size",kind,13);}skin.SetStylebox("normal","LineEdit",box(new Color("131e2a"),new Color("344356"),5,7));skin.SetStylebox("normal","TextEdit",box(new Color("131e2a"),new Color("344356"),5,8));skin.SetStylebox("panel","Tree",box(new Color("17212d"),new Color("17212d"),6,4));skin.SetStylebox("selected","Tree",box(new Color("214e4c"),new Color("3b8072"),4,3));skin.SetStylebox("selected_focus","Tree",box(new Color("246255"),new Color("6ae2c3"),4,3));skin.SetConstant("v_separation","Tree",0);skin.SetConstant("button_margin","Tree",0);skin.SetColor("font_color","Label",new Color("c9d8e6"));skin.SetColor("font_color","Tree",new Color("d5e5ef"));owner.Theme=skin;
    }
    public Button button(Control owner,Node parent,string text,Variant action,string tip,string iconName)
    {
        var button=new Button{Text=text,TooltipText=tip,CustomMinimumSize=new Vector2(0,parent.HasMeta("compact_toolbar")?28:32),FocusMode=Control.FocusModeEnum.None};if(iconName.Length>0){button.Icon=icon(owner,iconName);button.ExpandIcon=true;button.AddThemeConstantOverride("icon_max_width",18);if(text.Length==0)button.CustomMinimumSize=new Vector2(34,button.CustomMinimumSize.Y);}parent.AddChild(button);owner.Call("_connect_button",button,action);return button;
    }
    public MenuButton menu(Control owner,Node parent,string label,GArray items)
    {
        var button=new MenuButton{Text=label,CustomMinimumSize=new Vector2(0,32)};parent.AddChild(button);var popup=button.GetPopup();popup.AddThemeStyleboxOverride("panel",box(new Color("172431"),new Color("416274"),9,10));popup.AddThemeStyleboxOverride("hover",box(new Color("285950"),new Color("519887"),5,5));popup.AddThemeConstantOverride("v_separation",12);foreach(var value in items)popup.AddItem(value.AsGodotArray()[0].AsString());owner.Call("_connect_menu",popup,items);return button;
    }
    public void clear(Node parent){foreach(var child in parent.GetChildren()){parent.RemoveChild(child);child.QueueFree();}}
